/* Generated by safe ES module refactor from the existing js/main.js implementation. */

export function showLoader(text) {
  let loader = document.getElementById("global-loader");
  if (!loader) {
    loader = document.createElement("div");
    loader.id = "global-loader";
    loader.innerHTML = `
      <div class="loader-circle"></div>
      <div class="loader-text" id="loader-text">Loading...</div>
    `;
    document.body.appendChild(loader);
  }

  const loaderText = document.getElementById("loader-text");
  if (loaderText) loaderText.textContent = text || "Loading...";
  loader.classList.add("active");
}

export function hideLoader() {
  const loader = document.getElementById("global-loader");
  if (loader) loader.classList.remove("active");
}
